//! Cargo-driven `fmifs.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is fmifs-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_InitializeFmIfs@12", Some(0x750c0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "InitializeFmIfs", Some(0x7ff22000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "InitializeFmIfs", Some(0x7ff22000000u64)),
        o => panic!("fmifs-cargo: unsupported arch {o}"),
    };

    Linker::new(target_json)
        .rust_staticlib("fmifs-rust")
        .resource_from_rc("dll/win32/fmifs/fmifs.rc", "fmifs_res")
        .spec2def("dll/win32/fmifs/fmifs.spec", "fmifs.dll")
        .spec_stubs()
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
